('322', 'LC-Shop-AD(Boostiny)-CM-OrderConfirmation-ALL(WL)-PXFLW_samsungksa', '12', '23', '(.*orderconfirmation)', '1', '1', '2026-10-16', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRc6bfd8cde63246ee8abe23e880a2ae2f/rules/RL4cb5dd7c1cfc4c17b13bba5ea5dfeed7', 'XLSX', '', NULL, NULL, NULL, '1', '2026-08-04 09:33:36', '0', '2026-06-03 00:00:00', '0', NULL, 'window.tagLayer = window.tagLayer  || [];\r\nwindow.tagLayer.push({\r\n    deployment: \'auto\',\r\n    data: event,\r\n    argument: {\r\n        id: \'samsungksa\'\r\n    }\r\n});\r\n\r\nvar boostiny_obj={};\r\nvar itm_arr=[];\r\nvar up_products=digitalData.ecommerce.transactionProducts;\r\nfor(var foo=0;foo<up_products.length;foo++){\r\n    itm_arr.push({\r\n        name:up_products[foo].modelDisplay,\r\n        price:up_products[foo].modelPrice,\r\n        categories: [\r\n            up_products[foo].pviType,\r\n            up_products[foo].pviSubtype\r\n        ]\r\n    });\r\n}\r\n\r\nvar baseUrl=\"https://track.arabytracking.net/direct/conversion\";\r\nboostiny_obj={\r\n        \"client\": \'samksa\',\r\n        \"order_id\": digitalData?.ecommerce?.transactionId, \r\n        \"currency\": digitalData?.page?.pageInfo?.currencyCode, \r\n        \"country\": digitalData?.page?.pageInfo?.siteCode?.split(\"_\")[0],  \r\n        \"coupon\": digitalData?.ecommerce?.transactionVoucherCode,\r\n        \"amount\": digitalData?.ecommerce?.transactionTotal, \r\n        \"items\":itm_arr\r\n}\r\n\r\nvar token=\'c8vOzHFWB89Ng8vxBUYul92bj0VH2V6LuxApbuULZjI\';\r\nvar xhr = new XMLHttpRequest();\r\n    xhr.open(\"POST\", baseUrl, true);\r\n    xhr.setRequestHeader(\"Content-Type\", \"application/json\");\r\n    if(token){\r\n      xhr.setRequestHeader(\'Authorization\', token);\r\n    }\r\n    xhr.send(JSON.stringify(boostiny_obj));'),
