('520', 'LC-AEM-AD(Firework)-CM(ALL)-WL-SDSME_fwb5-8249346652d7', '2', '6', '(.*)', '1', '1', '2026-10-29', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRa7cdc4dd00c24675812c3d05053e3cf3/rules/RL9bafc8c9f20e4355a1b0b50c613dcf93', 'Alaa & shereen', 'alaa.a@samsung.com', '1', NULL, NULL, '1', '2026-08-20 16:47:18', '1', '2026-06-26 13:45:38', '0', NULL, 'var script = document.createElement(\'script\');\r\nscript.src = \"https://asset.fwcdn3.com/js/fwn.js\";\r\nscript.type = \'text/javascript\';\r\nscript.async = true;\r\ndocument.head.appendChild(script);'),
('521', 'LC-AEM-AD(Firework)-Cart-ATC-SDSME_fwb5-8249346652d7', '2', '6', '[an-tr=\"bridge_add on-flagship pdp-cta-cart\"], [data-cart=\"true\"], [canaddtocart=\"true\"]', '1', '1', '2026-10-29', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRa7cdc4dd00c24675812c3d05053e3cf3/rules?filter%5Bname%5D=CONTAINS+LC-AEM-AD(Firework)-Cart-ATC-SDSME_fwb5-8249346652d7', 'Alaa & shereen', 'alaa.a@samsung.com', '1', NULL, NULL, '1', '2026-08-20 16:47:18', '1', '2026-06-26 13:45:38', '0', NULL, 'var currency = this.getAttribute(\'data-modelcurrency\') ?? \'N/A\';\r\nvar modelprice = this.getAttribute(\'data-modelprice\');\r\nvar price = this.getAttribute(\'data-price\');\r\nvar saveprice = this.getAttribute(\'data-save-price\');\r\nvar discountprice = this.getAttribute(\'data-discountprice\');\r\nvar originalprice = this.getAttribute(\'data-original-price\');\r\nvar subtotal = modelprice ?? price;\r\nvar total_discounts = saveprice ?? (modelprice - discountprice);\r\n\r\nvar bridgeAttr = this.getAttribute(\'an-la\');\r\nvar isBridge = (bridgeAttr == \"add-on:continue\" || bridgeAttr == \"add-on:go to cart\");\r\nvar line_items = [];\r\nvar modelcode = this.getAttribute(\'data-modelcode\');\r\nvar quantity = this.getAttribute(\'data-modelqty\');\r\nvar price = this.getAttribute(\'data-discountprice\');\r\nvar modelname = this.getAttribute(\'data-modeldisplay\');\r\n\r\nif (isBridge) {\r\n   modelcode = modelcode.split(\',\');\r\n   quantity = quantity.split(\',\');\r\n   price = price.split(\',\');\r\n   modelname = modelname.split(\',\');\r\n\r\n   modelprice = modelprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   subtotal = modelprice.reduce(function(sum, value) { return sum + value; }, 0);\r\n\r\n   discountprice = discountprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   discountprice = discountprice.reduce(function(sum, value) { return sum + value; }, 0);\r\n\r\n   total_discounts = subtotal - discountprice;\r\n\r\n    line_items = modelcode.map(function(code, index) {\r\n        return {\r\n            \"sku\": code.trim(),\r\n            \"quantity\": quantity[index] ? quantity[index].trim() : null,\r\n            \"price\": price[index] ? price[index].trim() : null,\r\n            \"name\": modelname[index] ? modelname[index].trim() : null,\r\n        };\r\n    });\r\n} else {\r\n    line_items = [{\r\n        \"sku\": modelcode,\r\n        \"quantity\": quantity,\r\n        \"price\": price,\r\n        \"name\": modelname,\r\n    }];\r\n}\r\n\r\nwindow._fwn.analytics.addToCart({\r\n    \"order_id\": \"N/A\",\r\n    \"currency\": currency,\r\n    \"subtotal\": subtotal,\r\n    \"total_discounts\": total_discounts,\r\n    \"order_value\": originalprice ? (originalprice - saveprice) : discountprice,\r\n    \"line_items\": line_items,\r\n});'),
('522', 'LC-Shop-AD(Firework)-CM(ALL)-WL-SDSME_fw6a-aa1422f0f16', '4', '6', '(.*)', '1', '1', '2026-10-30', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRc290a80a826d4ceeb30cfcbe59148dbc/rules/RL17a6958871eb494b8048b976d9804a9f', 'Alaa & shereen', 'alaa.a@samsung.com', '1', NULL, NULL, '1', '2026-08-20 16:47:18', '1', '2026-06-26 13:47:37', '0', NULL, 'var script = document.createElement(\'script\');\r\nscript.src = \"https://asset.fwcdn3.com/js/fwn.js\";\r\nscript.type = \'text/javascript\';\r\nscript.async = true;\r\ndocument.head.appendChild(script);'),
('523', 'LC-Shop-AD(Firework)-OrderConfirmation-WL-SDSME_fw6a-aa1422f0f16', '4', '6', '^shop order confirmation$', '1', '1', '2026-10-30', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRc290a80a826d4ceeb30cfcbe59148dbc/rules/RLf3ba9b7c3eb644ad892030e7bbd2711e', 'Alaa & shereen', 'alaa.a@samsung.com', '1', NULL, NULL, '1', '2026-08-20 16:47:18', '1', '2026-06-26 13:47:37', '0', NULL, 'if (!window.fwOrderCount) window.fwOrderCount = 0; //prevent duplicate orders\r\n\r\nvar eCommerce = digitalData.ecommerce;\r\nvar transactionId = eCommerce.transactionId;\r\n\r\nif (transactionId == \'\' || window.fwOrderCount > 1) return false; // on page refresh\r\n\r\nvar pageInfo = digitalData.page.pageInfo;\r\nvar subTotal = 0;\r\nvar lineItems = [];\r\nvar transactionTotal = eCommerce.transactionTotal;\r\n\r\nfor (const item of eCommerce.transactionProducts) {\r\n    subTotal += item.modelPrice;\r\n    lineItems.push({\r\n        sku: item.modelCode != \'\' ? item.modelCode : item.modelName,\r\n        quantity: item.modelUnit,\r\n        price: item.modelPrice,\r\n        name: item.modelDisplay,\r\n    });\r\n}\r\n\r\nvar totalDiscounts = 0;\r\nif (subTotal > 0)\r\n  totalDiscounts = subTotal - transactionTotal;\r\n\r\nlet purchasePayload = {\r\n    \"order_id\": transactionId,\r\n    \"currency\": pageInfo.currencyCode,\r\n    \"subtotal\": subTotal,\r\n    \"total_discounts\": totalDiscounts,\r\n    \"order_value\": transactionTotal,\r\n    \"line_items\": lineItems,\r\n};\r\n\r\nwindow._fwn.analytics.purchase(purchasePayload);\r\nwindow.fwOrderCount++;'),
