('541', 'LC-AEM-AD(Firework)-Cart-ATC-SDSME_fw11-fb62c6a234cf', '8', '6', '[an-tr=\"bridge_add on-flagship pdp-cta-cart\"], [data-cart=\"true\"], [canaddtocart=\"true\"]', '1', '1', '2026-11-02', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PR61d5f565065949ee998624876c792317/rules/RL8e04fd12195f46719850c187bf3ecc54', 'Yara Mustafa Afifi', 'yara.a@partner.samsung.com', '1', NULL, NULL, '1', '2026-08-24 09:19:09', '1', '2026-07-01 12:41:31', '0', NULL, 'var currency = this.getAttribute(\'data-modelcurrency\') ?? \'N/A\';\r\nvar modelprice = this.getAttribute(\'data-modelprice\');\r\nvar price = this.getAttribute(\'data-price\');\r\nvar saveprice = this.getAttribute(\'data-save-price\');\r\nvar discountprice = this.getAttribute(\'data-discountprice\');\r\nvar originalprice = this.getAttribute(\'data-original-price\');\r\nvar subtotal = modelprice ?? price;\r\nvar total_discounts = saveprice ?? (modelprice - discountprice);\r\n\r\nvar bridgeAttr = this.getAttribute(\'an-la\');\r\nvar isBridge = (bridgeAttr == \"add-on:continue\" || bridgeAttr == \"add-on:go to cart\");\r\nvar line_items = [];\r\nvar modelcode = this.getAttribute(\'data-modelcode\');\r\nvar quantity = this.getAttribute(\'data-modelqty\');\r\nvar price = this.getAttribute(\'data-discountprice\');\r\nvar modelname = this.getAttribute(\'data-modeldisplay\');\r\n\r\nif (isBridge) {\r\n   modelcode = modelcode.split(\',\');\r\n   quantity = quantity.split(\',\');\r\n   price = price.split(\',\');\r\n   modelname = modelname.split(\',\');\r\n\r\n   modelprice = modelprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   subtotal = modelprice.reduce(function(sum, value) { return sum + value; }, 0);\r\n\r\n   discountprice = discountprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   discountprice = discountprice.reduce(function(sum, value) { return