('617', 'LC-Shop-AD(Pinterest)-CM-WL-SDSME_2612781677612', '12', '7', '(.*)', '1', '1', '2026-11-25', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRc6bfd8cde63246ee8abe23e880a2ae2f/rules?filter%5Bname%5D=CONTAINS+LC-Shop-AD(Pinterest)-CM-WL-SDSME_2612781677612', 'Tabrez Firoz', 'tabrez.firoz@dentsu.com', '1', NULL, NULL, '1', '2026-09-28 14:00:13', '1', '2026-09-24 14:11:53', '0', NULL, '!function (e) {\r\n  if (!window.pintrk) {\r\n    window.pintrk = function () {\r\n      window.pintrk.queue.push(Array.prototype.slice.call(arguments))\r\n    }; var\r\n      n = window.pintrk; n.queue = [], n.version = \"3.0\"; var\r\n        t = document.createElement(\"script\"); t.async = !0, t.src = e; var\r\n          r = document.getElementsByTagName(\"script\")[0];\r\n    r.parentNode.insertBefore(t, r)\r\n  }\r\n}(\"https://s.pinimg.com/ct/core.js\");\r\npintrk(\'load\', \'2612781677612\');\r\npintrk(\'page\');\r\n\r\n(function () {\r\n  if (typeof window.pintrk === \'undefined\') {\r\n    var noscript = document.createElement(\"img\");\r\n    noscript.height = 1;\r\n    noscript.width = 1;\r\n    noscript.style = \"display:none;\";\r\n    noscript.src = \"https://ct.pinterest.com/v3/?event=init&tid=2612781677612&noscript=1\";\r\n    document.head.appendChild(noscript);\r\n  }\r\n})();\r\n\r\nvar pageTrack = digitalData.page.pageInfo.pageTrack;\r\nvar ecommerce = digitalData.ecommerce;\r\nvar transactionId = ecommerce.transactionId;\r\nvar transactionProducts = ecommerce.transactionProducts;\r\nconst unixTimestamp = Math.floor(Date.now() / 1000);\r\nconst eventId = \'evt_\' + unixTimestamp;\r\n\r\nif (typeof window.pintrkCheckoutSent === \'undefined\') {\r\n  window.pintrkCheckoutSent = false;\r\n}\r\n\r\nswitch (pageTrack) {\r\n  case \'shop checkout\':\r\n    if (transactionId && !window.pintrkCheckoutSent) {\r\n      sendEvent(\'initiatecheckout\');\r\n      window.pintrkCheckoutSent = true;\r\n    }\r\n    break;\r\n\r\n  case \'shop order confirmation\':\r\n    if (transactionId) {\r\n      sendEvent(\'checkout\');\r\n    }\r\n    break;\r\n\r\n  default:\r\n    pintrk(\'track\', \'pagevisit\', { event_id: eventId });\r\n}\r\n\r\nfunction sendEvent(eventName) {\r\n  const line_items = transactionProducts.map(({\r\n      modelCode: product_id,\r\n      pviType: product_category,\r\n      pviSubtype: product_variant,\r\n      modelDisplay: product_name,\r\n      modelUnit: product_quantity,\r\n      modelRevenue: product_price\r\n    }) => ({ product_id, product_category, product_variant, product_name, product_quantity, product_price }));\r\n\r\n  pintrk(\'track\', eventName, {\r\n    event_id: eventId,\r\n    value: ecommerce.transactionTotal,\r\n    order_quantity: transactionProducts.length,\r\n    currency: digitalData.page.pageInfo.currencyCode,\r\n    order_id: transactionId,\r\n    line_items: line_items,\r\n  });\r\n}'),
