('620', 'LC-AEM-AD(Meta)-PD-ATC-SDSME_2611523569055248', '7', '9', '[an-tr=\"bridge_add on-flagship pdp-cta-cart\"], [data-cart=\"true\"], [canaddtocart=\"true\"]', '7', '1', '2026-11-29', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PR84237b02f2524aae898e192f7bab097a/rules/RL99bc9c87a60f4433be6bd06e7f5e6720', 'Muhammad Hussnain Hamid', 'hussnain.h@partner.samsung.com', '1', NULL, NULL, '1', '2026-09-29 10:42:47', '1', '2026-09-28 16:36:08', '0', NULL, 'var uniqueEventID = _satellite.getVar(\'General - Unique Event ID\');\r\nvar sitecode = _satellite.getVar(\'Site Code\');\r\nvar eventId = _satellite.getVar(\'General - Get Event - ID\');\r\nvar currencyCode = _satellite.getVar(\'Currency Code\');\r\nvar pageType = digitalData.page.pageInfo.pageTrack;\r\n\r\nvar currency = this.getAttribute(\'data-modelcurrency\') ?? (digitalData.page?.pageInfo?.currencyCode ?? \'AED\');\r\nvar modelprice = this.getAttribute(\'data-modelprice\');\r\nvar price = this.getAttribute(\'data-price\');\r\nvar modelcode = this.getAttribute(\'data-modelcode\');\r\nvar quantity = this.getAttribute(\'data-modelqty\') ?? 1;\r\nvar modelname = this.getAttribute(\'data-modeldisplay\');\r\nvar category = this.getAttribute(\'data-pvisubtype\') ?? this.getAttribute(\'data-pvitype\');\r\n\r\nvar bridgeAttr = this.getAttribute(\'an-la\');\r\nvar isBridge = (bridgeAttr == \"add-on:continue\" || bridgeAttr == \"add-on:go to cart\");\r\nvar contents = [];\r\nvar totalPrice = 0;\r\nvar itemCount = quantity;\r\nvar itemPrice = modelprice ? modelprice : price;\r\n\r\nif (isBridge) {\r\n    modelcode = modelcode ? modelcode.split(\',\') : [];\r\n    quantity = quantity ? quantity.split(\',\').map(v => Number(v.trim())) : [];\r\n    price = itemPrice ? itemPrice.split(\',\').map(v => Number(v.trim())) : [];\r\n    modelname = modelname ? modelname.split(\';\') : [];\r\n    category = category ? category.split(\',\') : [];\r\n\r\n    contents = modelcode.map(function(code, index) {\r\n        return {\r\n            id: code.trim(),\r\n            quantity: quantity[index] ? quantity[index] : null,\r\n            name: modelname[index] ? modelname[index].trim() : null,\r\n            category: category[index] ? category[index].trim() : null,\r\n            price: price[index] ? price[index] : null,\r\n        };\r\n    });\r\n\r\n    totalPrice = price.reduce(function(sum, value) { return sum + value; }, 0);\r\n    itemCount = quantity.reduce(function(sum, value) { return sum + value; }, 0);\r\n} else {\r\n    contents = [{\r\n        id: modelcode,\r\n        quantity: quantity,\r\n        name: modelname,\r\n        category: category,\r\n        price: Number(itemPrice),\r\n    }];\r\n\r\n    totalPrice = itemPrice;\r\n}\r\n\r\nfbq(\'track\', \'AddToCart\', {\r\n  content_ids: contents.map(product => product.id),\r\n  content_type: \'product\',\r\n  contents: contents,\r\n  value: totalPrice,\r\n  currency: currencyCode\r\n}, { eventID: uniqueEventID });\r\n\r\n// EDDL Data Layer Push\r\neddlDataLayer.push({\r\n  \'event\': \'marketing_event_meta\',\r\n  \'marketing_data\': {\r\n    \'facebook\': {\r\n      \'event_name\': \'AddToCart\',\r\n      \'event_id\': uniqueEventID,\r\n      \'site_code\': sitecode,\r\n      \'currency\': currencyCode\r\n    }\r\n  },\r\n  \'custom_values\': {\r\n    \'ecommerce\': {\r\n      \'items\': [\r\n        {\r\n          \'item_id\': String(contents.map(product => product.id)),\r\n        }\r\n      ]\r\n    }\r\n  }\r\n});\r\n\r\n// clear marketing data\r\neddlDataLayer.push({ \'marketing_data\': undefined });'),
