ry = category ? category.split(\',\') : [];\r\n\r\n    contents = modelcode.map(function(code, index) {\r\n        return {\r\n            id: code.trim(),\r\n            quantity: quantity[index] ? quantity[index] : null,\r\n            name: modelname[index] ? modelname[index].trim() : null,\r\n            category: category[index] ? category[index].trim() : null,\r\n            price: price[index] ? price[index] : null,\r\n        };\r\n    });\r\n\r\n    totalPrice = price.reduce(function(sum, value) { return sum + value; }, 0);\r\n    itemCount = quantity.reduce(function(sum, value) { return sum + value; }, 0);\r\n} else {\r\n    contents = [{\r\n        id: modelcode,\r\n        quantity: quantity,\r\n        name: modelname,\r\n        category: category,\r\n        price: Number(itemPrice),\r\n    }];\r\n\r\n    totalPrice = itemPrice;\r\n}\r\n\r\nfbq(\'track\', \'AddToCart\', {\r\n  content_ids: contents.map(product => product.id),\r\n  content_type: \'product\',\r\n  contents: contents,\r\n  value: totalPrice,\r\n  currency: currencyCode\r\n}, { eventID: uniqueEventID });\r\n\r\n// EDDL Data Layer Push\r\neddlDataLayer.push({\r\n  \'event\': \'marketing_event_meta\',\r\n  \'marketing_data\': {\r\n    \'facebook\': {\r\n      \'event_name\': \'AddToCart\',\r\n      \'event_id\': uniqueEventID,\r\n      \'site_code\': sitecode,\r\n      \'currency\': currencyCode\r\n    }\r\n  },\r\n  \'custom_values\': {\r\n    \'ecommerce\': {\r\n      \'items\': [\r\n        {\r\n          \'item_id\': String(contents.map(product => product.id)),\r\n        }\r\n      ]\r\n    }\r\n  }\r\n});\r\n\r\n// clear marketing data\r\neddlDataLayer.push({ \'marketing_data\': undefined });'),
('622', 'LC-AEM-AD(Firework)-CM-WL-SDSME_floating_video_player', '8', '6', 'isHomeOrMobile', '4', '1', '2026-11-29', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PR61d5f565065949ee998624876c792317/rules/RLb7ab43cdd05f4b758ac78743d00c6837', 'Arbash Javed', 'arbash.j@samsung.com', '1', NULL, NULL, '1', '2026-09-29 14:59:40', '1', '2026-09-29 11:37:35', '0', NULL, 'document.addEventListener(\'fw:player:quit\', function(event) {\r\n    setCookie(\'fw:player:quit\', cookieBannerValue, 0.5);\r\n})\r\n \r\nvar cookieBannerValue = \'1\';\r\n \r\nfunction setCookie(cName, cValue, expMins) {\r\n    var date = new Date();\r\n    date.setTime(date.getTime() + (expMins * 60 * 1000));\r\n    var expires = \"expires=\" + date.toUTCString();\r\n    document.cookie = cName + \"=\" + cValue + \"; \" + expires + \"; path=/\";\r\n}\r\n \r\n \r\nfunction getCookie(cname) {\r\n    var name = cname + \"=\";\r\n    var ca = document.cookie.split(\';\');\r\n    for (var i = 0; i < ca.length; i++) {\r\n        var chr = ca[i];\r\n        while (chr.charAt(0) == \' \') {\r\n            chr = chr.substring(1);\r\n        }\r\n        if (chr.indexOf(name) == 0) {\r\n            return chr.substring(name.length, chr.length);\r\n        }\r\n    }\r\n    return \"\";\r\n}\r\n \r\n \r\nif (getCookie(\'fw:player:quit\') == \"\") {\r\n    var script_tag = document.createElement(\'script\');\r\n    script_tag.src = \"https://asset.fwcdn3.com/js/storyblock.js\";\r\n    script_tag.type = \'text/javascript\';\r\n    script_tag.async = true;\r\n    document.head.appendChild(script_tag);\r\n\r\n    var node = document.createElement(\"fw-storyblock\");\r\n    node.setAttribute(\"id\", \"firework-embed\");\r\n    node.setAttribute(\"channel\", \"samsung_saudi_arabia\");\r\n    node.setAttribute(\"playlist\", \"gK4OY8\");\r\n    node.setAttribute(\"autoplay\", \"true\");\r\n    node.setAttribute(\"mode\", \"pinned\");\r\n    node.setAttribute(\"player_placement\", \"bottom-right\");\r\n    document.body.prepend(node);\r\n}'),
