-- Martech TMS Database Backup
-- Date: 2026-09-30 08:38:18
-- --------------------------------------------------------

SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `activity_log_comments`;
CREATE TABLE `activity_log_comments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `log_id` int(11) NOT NULL COMMENT 'This is reference to the activity_logs table, activity_logs.id',
  `comment` longtext NOT NULL COMMENT 'This is the description/details of the comment',
  `type` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'Numerical, (1) User-generated comment (2) Auto-generated comment',
  `commented_by` tinyint(4) NOT NULL COMMENT 'This is reference to the users table, users.id',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1818 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



















DROP TABLE IF EXISTS `activity_log_files`;
CREATE TABLE `activity_log_files` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `file_name` varchar(200) NOT NULL COMMENT 'This is the file name',
  `file_path` varchar(500) NOT NULL COMMENT 'This is the path of the file',
  `log_id` int(11) NOT NULL COMMENT 'This is reference to the activity_logs table, activity_logs.id',
  `created_by` tinyint(4) NOT NULL COMMENT 'This is reference to the users table, users.id',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `activity_logs`;
CREATE TABLE `activity_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(500) NOT NULL COMMENT 'This is the title of the task',
  `description` longtext NOT NULL COMMENT 'This is the summary / overview of the task',
  `subsidiary_id` int(11) NOT NULL COMMENT 'This is reference to the subsidiaries table, subsidiaries.id',
  `department_id` varchar(255) DEFAULT NULL COMMENT 'This is the department which is the requestor belongs to',
  `team_id` int(11) NOT NULL COMMENT 'This is the team where the user who logged the task belongs to, (1) Media Tagging (2) DWF (3) CRM (4) Spoke (5) Other',
  `project` varchar(255) NOT NULL DEFAULT 'Generic' COMMENT 'This is the project / group type of each task mainly for categorization',
  `ticket_id` varchar(100) DEFAULT NULL COMMENT 'This is reference to the jira_history and tag_requests table, ticket_id fields. This will connect with the tag using the tag_id of the tag_requests table',
  `mt_jira_ticket` varchar(50) DEFAULT NULL COMMENT 'This is the ticket ID for the Martech JIRA',
  `assignee` int(11) NOT NULL COMMENT 'This is reference to the users table, users.id',
  `requested_by` varchar(200) DEFAULT NULL COMMENT 'This is the name of the requestor',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'This refers to Constants.php Activity_Logs_Status',
  `type` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'This refers to Constants.php Activity_Types',
  `size` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'This indicates how big this task is (1) S (2) M (3) L (4) XL (5) Sprint',
  `priority` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'This indicates how critical the task is (1) Low (2) Medium (3) High (4) Critical (5) Blocker (10) Default / Normal',
  `requested_date` datetime DEFAULT NULL COMMENT 'This is the date when this task was requested by requested_by person',
  `start_date` datetime DEFAULT NULL COMMENT 'This is the date when the assignee started this task',
  `finished_date` datetime DEFAULT NULL COMMENT 'This is the date this task status was changed to Completed/Finished',
  `created_at` datetime NOT NULL COMMENT 'This is the date this task was logged into the system',
  `created_by` int(11) NOT NULL DEFAULT 0 COMMENT 'This refers to the users table, who created the task, users.id',
  `updated_at` datetime NOT NULL,
  `updated_by` int(11) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) DEFAULT NULL,
  `campaign_status` int(11) DEFAULT NULL COMMENT 'This is mainly for DWF team, indicates the categorization of the campaign (1) New (2) Existing',
  `campaign_id` varchar(200) DEFAULT NULL COMMENT 'This is mainly for DWF team, indicates the campaign ID',
  `labels` varchar(500) DEFAULT NULL COMMENT 'These are array labels, for categorization of the tasks',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=657 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;








DROP TABLE IF EXISTS `ai_conversations`;
CREATE TABLE `ai_conversations` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) unsigned NOT NULL,
  `tag_id` int(11) unsigned DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `messages` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `tag_id` (`tag_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `countries`;
CREATE TABLE `countries` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `code` varchar(10) NOT NULL,
  `updated_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `jira_history`;
CREATE TABLE `jira_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ticket_id` varchar(150) NOT NULL COMMENT 'This is used to map the related activity_log and tag_request, the same field ticket_id',
  `type` varchar(150) NOT NULL COMMENT 'This refers to Constants.php JIRA_TICKET_TYPES',
  `comments` varchar(500) DEFAULT NULL,
  `tag_id` int(11) NOT NULL DEFAULT 0 COMMENT 'This refers to the related tag, tags.id',
  `property_id` int(11) NOT NULL DEFAULT 0 COMMENT 'This refers to the related property, properties.id',
  `subsidiary_id` int(11) NOT NULL DEFAULT 0 COMMENT 'This refers to the related subsidiary, subsidiaries.id',
  `is_active` int(11) NOT NULL DEFAULT 1,
  `file_path` varchar(200) DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'This refers to the related user who created the entry, users.id',
  `created_at` datetime NOT NULL,
  `updated_by` int(11) NOT NULL DEFAULT 0,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1476 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
















DROP TABLE IF EXISTS `languages`;
CREATE TABLE `languages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(10) NOT NULL,
  `updated_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `version` varchar(255) NOT NULL,
  `class` varchar(255) NOT NULL,
  `group` varchar(255) NOT NULL,
  `namespace` varchar(255) NOT NULL,
  `time` int(11) NOT NULL,
  `batch` int(11) unsigned NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `mt_jira_api_log`;
CREATE TABLE `mt_jira_api_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) DEFAULT NULL,
  `request_type` varchar(50) NOT NULL COMMENT 'e.g., CREATE_ISSUE, UPDATE_STATUS',
  `endpoint_url` varchar(255) NOT NULL,
  `payload` text DEFAULT NULL,
  `response_body` text DEFAULT NULL,
  `status_code` int(11) DEFAULT NULL,
  `error_message` varchar(255) DEFAULT NULL,
  `status` enum('SUCCESS','FAILED','PENDING_RETRY') NOT NULL DEFAULT 'FAILED',
  `retry_count` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1624 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


















DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `sender_id` int(11) NOT NULL,
  `task_id` int(11) NOT NULL,
  `message` varchar(255) NOT NULL,
  `is_read` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=541 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;







DROP TABLE IF EXISTS `organizations`;
CREATE TABLE `organizations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `updated_by` tinyint(4) NOT NULL DEFAULT 0,
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `project_comments`;
CREATE TABLE `project_comments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_name` varchar(255) NOT NULL COMMENT 'This refers to the project where this comment is related to, activity_logs.project',
  `comment` text NOT NULL COMMENT 'This is the comment detail',
  `commented_by` tinyint(4) NOT NULL COMMENT 'This refers to who made the comment/update, users.id',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `project_name` (`project_name`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `properties`;
CREATE TABLE `properties` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `is_epp` tinyint(4) NOT NULL DEFAULT 0,
  `is_shop` tinyint(4) NOT NULL DEFAULT 0,
  `subsidiary_id` int(11) NOT NULL COMMENT 'Refers to the subsidiaries table',
  `country_id` int(11) NOT NULL,
  `language_id` tinyint(4) NOT NULL DEFAULT 1,
  `website` varchar(200) NOT NULL,
  `ref_link` varchar(500) NOT NULL COMMENT 'Links to AL',
  `updated_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `renewal_justification`;
CREATE TABLE `renewal_justification` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tag_id` int(11) NOT NULL COMMENT 'This refers to the tag where this justification belongs to, tags.id',
  `renew` char(4) DEFAULT NULL COMMENT '(Y) The tag will be renewed, (N) The tag is marked not for renewal',
  `justification` varchar(150) DEFAULT NULL COMMENT 'The justification why the tag still needs to be renewed',
  `duration` varchar(150) DEFAULT NULL COMMENT 'Identifies how long the tag needs to be implemented',
  `created_by` tinyint(4) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  `updated_by` int(11) NOT NULL DEFAULT 0,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=636 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;








DROP TABLE IF EXISTS `renewal_logs`;
CREATE TABLE `renewal_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ticket_id` varchar(150) NOT NULL,
  `property_id` tinyint(4) NOT NULL,
  `library_name` varchar(150) NOT NULL,
  `vendor` varchar(500) NOT NULL,
  `al_end_date` date NOT NULL,
  `user` tinyint(4) NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=366 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;





DROP TABLE IF EXISTS `role_permissions`;
CREATE TABLE `role_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_id` int(11) NOT NULL,
  `permission_key` varchar(100) NOT NULL,
  `permission_value` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `role_permission_unique` (`role_id`,`permission_key`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `subsidiaries`;
CREATE TABLE `subsidiaries` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(10) NOT NULL,
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `updated_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `tag_request_files`;
CREATE TABLE `tag_request_files` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `file_name` varchar(200) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `type` tinyint(4) NOT NULL,
  `request_id` tinyint(4) NOT NULL,
  `created_by` tinyint(4) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=142 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



DROP TABLE IF EXISTS `tag_requests`;
CREATE TABLE `tag_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `new_tag_ticket` varchar(150) DEFAULT NULL COMMENT 'Refers to the ticket ID of the New Tag Request',
  `tags` varchar(200) NOT NULL COMMENT 'These are the related tags for this request',
  `property_id` tinyint(4) NOT NULL COMMENT 'This refers to the property which this request belongs, properties.id',
  `vendor_id` tinyint(4) NOT NULL COMMENT 'This refers to the vendor which this request/tags belongs to, vendors.id',
  `status` tinyint(4) NOT NULL COMMENT 'This refers to Constants.php STATUS_REQUESTS',
  `type` tinyint(4) NOT NULL COMMENT 'This refers to Constants.php REQUEST_TYPES',
  `new_rule_ticket` varchar(150) DEFAULT NULL COMMENT 'Refers to the ticket ID of the New Rule Request',
  `update_rule_ticket` varchar(150) DEFAULT NULL,
  `requester_name` varchar(200) DEFAULT NULL COMMENT 'This is the user who requested the tag implementation',
  `requester_email` varchar(200) DEFAULT NULL COMMENT 'This is the email of the user who requested the tag implementation',
  `requester_organization` tinyint(4) DEFAULT NULL COMMENT 'This is the organization of the user who requested the tag implementation',
  `updated_by` tinyint(4) NOT NULL DEFAULT 0,
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




DROP TABLE IF EXISTS `tags`;
CREATE TABLE `tags` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(500) NOT NULL COMMENT 'The name of the tag',
  `property_id` int(11) NOT NULL COMMENT 'This refers to the property this tag belongs to, properties.id',
  `vendor_id` int(11) NOT NULL DEFAULT 0 COMMENT 'This refers to the vendor this tag belongs to, vendors.id',
  `conditions` varchar(200) DEFAULT NULL COMMENT 'This is the tag condition set in Adobe Launch',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'This refers to Constants.php STATUS',
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `al_end_date` date DEFAULT NULL COMMENT 'This is the Adobe Launch tag expiry date',
  `requested_date` date DEFAULT NULL COMMENT 'If this is not null, this is the new date for approval to HQ for the tag extension',
  `ref_link` varchar(500) NOT NULL COMMENT 'This is an external link to Adobe Launch tag',
  `requester_name` varchar(150) DEFAULT NULL COMMENT 'This is the user who requested the tag to be implemented',
  `requester_email` varchar(150) DEFAULT NULL COMMENT 'This is the email of requester_name',
  `requester_organization` tinyint(4) DEFAULT NULL COMMENT 'This is the organization of requester_name',
  `new_tag_request` tinyint(4) DEFAULT NULL,
  `new_rule_request` tinyint(4) DEFAULT NULL,
  `updated_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `deleted_at` datetime DEFAULT NULL,
  `js_code` longtext DEFAULT NULL COMMENT 'This is the script attached to the tag in Adobe Launch',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=624 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;








DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `first_name` varchar(150) NOT NULL,
  `last_name` varchar(150) NOT NULL,
  `username` varchar(150) NOT NULL,
  `password` varchar(500) NOT NULL,
  `account_type` tinyint(4) NOT NULL DEFAULT 0,
  `role_id` int(11) DEFAULT NULL,
  `profile_photo` varchar(255) DEFAULT NULL,
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `vendors`;
CREATE TABLE `vendors` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL COMMENT 'The name of the vendor - 3rd party',
  `about` varchar(500) DEFAULT NULL COMMENT 'The overview of what the vendor does',
  `reason` varchar(500) DEFAULT NULL COMMENT 'The reason why the vendor needs the implementation',
  `tag_purpose` varchar(500) DEFAULT NULL COMMENT 'What the implemented tags do',
  `collected_data` varchar(500) DEFAULT NULL,
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `updated_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `updated_at` datetime DEFAULT NULL,
  `created_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `created_at` datetime DEFAULT NULL,
  `deleted_by` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Account ID of PIC',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


SET FOREIGN_KEY_CHECKS=1;
